+describe("view_order_reversed", () => {
+    const add = (state, id) =>
+        reduceFlows(
+            state,
+            flowActions.FLOWS_ADD({
+                flow: { ...TFlow(), id },
+                matching_filters: {},
+            }),
+        );
+    const ids = (state) => state.view.map((f) => f.id);
+    // @ts-expect-error only the relevant option is needed
+    const reversed = (value: boolean) => ({ view_order_reversed: { value } });
+
+    it("reads the option from OPTIONS_RECEIVE and OPTIONS_UPDATE", () => {
+        let state = reduceFlows(undefined, OPTIONS_RECEIVE(reversed(true)));
+        expect(state.viewOrderReversed).toBe(true);
+        state = reduceFlows(state, OPTIONS_UPDATE(reversed(false)));
+        expect(state.viewOrderReversed).toBe(false);
+    });
+
+    it("inserts new flows at the front when reversed", () => {
+        let state = reduceFlows(undefined, OPTIONS_RECEIVE(reversed(true)));
+        state = add(add(add(state, "a"), "b"), "c");
+        expect(ids(state)).toEqual(["c", "b", "a"]);
+        expect(state._viewIndex.get("c")).toBe(0);
+        expect(state._viewIndex.get("a")).toBe(2);
+    });
+
+    it("inserts new flows at the back when not reversed", () => {
+        let state = reduceFlows(undefined, OPTIONS_RECEIVE(reversed(false)));
+        state = add(add(add(state, "a"), "b"), "c");
+        expect(ids(state)).toEqual(["a", "b", "c"]);
+    });
+
+    it("prefers an active column sort", () => {
+        let state = reduceFlows(undefined, OPTIONS_RECEIVE(reversed(true)));
+        state = reduceFlows(
+            state,
+            flowActions.setSort({ column: "path", desc: false }),
+        );
+        state = add(add(state, "a"), "b");
+        // identical sort keys: stable append order, not front insertion
+        expect(ids(state)).toEqual(["a", "b"]);
+    });
+});
